// @generated by:gauntlet run:godseye-local-jobs
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { deferred, type JobsFixture, jobsFixture, SenderFixture } from "./jobs-helpers.js";

describe("T19 transactional outbox", () => {
  let fixture: JobsFixture;
  beforeEach(async () => {
    fixture = await jobsFixture();
  });
  afterEach(async () => {
    await fixture.store.close();
  });
  const reconcile = (
    id: string,
    expectedState: "unknown" | "reconciling" | "held",
    resolution: "observed_delivered" | "observed_absent_retry" | "abandon",
  ) =>
    fixture
      .jobs()
      .reconcileOutbox(
        fixture.freshOwner(),
        id,
        { expectedState, resolution, evidenceRef: "operator:evidence-1" },
        randomUUID(),
      );

  it("never emits an intent whose business transaction rolled back", async () => {
    await expect(
      fixture.jobs().transact(async (tx) => {
        await fixture.jobs().enqueueOutbox(tx, fixture.intent("rolled-back-0001"));
        throw new Error("crash before business commit");
      }),
    ).rejects.toThrow();
    await fixture.jobs().tick();
    expect(await fixture.outboxRows()).toHaveLength(0);
    expect(fixture.sender.sends).toHaveLength(0);
  });
  it("recovers a committed intent after a crash between commit and send", async () => {
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("committed-0001")));
    const restarted = fixture.build();
    await restarted.jobs.tick();
    expect(fixture.sender.sends.map((send) => send.effectKey)).toEqual(["committed-0001"]);
    expect((await fixture.outboxRows())[0]).toMatchObject({ state: "delivered", attempts: 1 });
  });
  it("deduplicates repeated intents by effect key and rejects a conflicting payload", async () => {
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("dedupe-key-0001")));
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("dedupe-key-0001")));
    await expect(
      fixture
        .jobs()
        .transact((tx) =>
          fixture.jobs().enqueueOutbox(tx, fixture.intent("dedupe-key-0001", { n: 2 })),
        ),
    ).rejects.toMatchObject({ code: "IDEMPOTENCY_CONFLICT" });
    await fixture.jobs().tick();
    await fixture.jobs().tick();
    expect(await fixture.outboxRows()).toHaveLength(1);
    expect(fixture.sender.sends).toHaveLength(1);
  });
  it("redelivers a lost acknowledgement to a deduplicating receiver at most once effectively", async () => {
    fixture.sender.behavior = async () => "applied-then-lost";
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("lost-ack-00001")));
    await fixture.jobs().tick();
    const [lost] = await fixture.outboxRows();
    expect(lost?.state).toBe("unknown");
    await reconcile(lost?.id ?? "", "unknown", "observed_absent_retry");
    fixture.sender.behavior = async () => ({ status: "delivered" });
    await fixture.jobs().tick();
    expect((await fixture.outboxRows())[0]?.state).toBe("delivered");
    expect(fixture.sender.sends).toHaveLength(2);
    expect(fixture.sender.applied.get("lost-ack-00001")).toBe(1);
  });
  const crashAfterClaim = async (target: JobsFixture, key: string) => {
    await target.jobs().transact((tx) => target.jobs().enqueueOutbox(tx, target.intent(key)));
    await target.store.db
      .update(schema.jobOutbox)
      .set({ state: "dispatching", attempts: 1, claimedAt: target.clock.now() })
      .where(eq(schema.jobOutbox.effectKey, key));
    target.clock.advance(120_000);
  };
  it("redelivers an abandoned claim only when the receiver deduplicates by effect key", async () => {
    await crashAfterClaim(fixture, "crash-claim-001");
    await fixture.jobs().tick();
    expect((await fixture.outboxRows())[0]).toMatchObject({ state: "delivered", attempts: 2 });
    expect(fixture.sender.applied.get("crash-claim-001")).toBe(1);
  });
  it("leaves an abandoned claim unknown when the receiver cannot deduplicate", async () => {
    const plain = await jobsFixture({ sender: new SenderFixture(false) });
    try {
      await crashAfterClaim(plain, "crash-claim-002");
      await plain.jobs().tick();
      await plain.jobs().tick();
      expect((await plain.outboxRows())[0]?.state).toBe("unknown");
      expect(plain.sender.sends).toHaveLength(0);
    } finally {
      await plain.store.close();
    }
  });
  it("never repeats an unknown delivery automatically", async () => {
    fixture.sender.behavior = async () => {
      throw new Error("timeout awaiting acknowledgement");
    };
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("unknown-0000001")));
    for (let i = 0; i < 3; i++) await fixture.jobs().tick();
    expect(fixture.sender.sends).toHaveLength(1);
    expect((await fixture.outboxRows())[0]?.state).toBe("unknown");
  });
  it("moves unknown deliveries into reconciliation when a probe cannot prove delivery", async () => {
    fixture.sender.enableInspection();
    fixture.sender.behavior = async () => ({ status: "unknown" });
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("probe-0000001")));
    await fixture.jobs().tick();
    await fixture.jobs().tick();
    const [row] = await fixture.outboxRows();
    expect(row?.state).toBe("reconciling");
    const done = await reconcile(row?.id ?? "", "reconciling", "observed_delivered");
    expect(done.state).toBe("delivered");
    expect(fixture.sender.sends).toHaveLength(1);
  });
  it("accepts a read-only probe that proves delivery", async () => {
    fixture.sender.enableInspection();
    fixture.sender.presence = "delivered";
    fixture.sender.behavior = async () => ({ status: "unknown" });
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("probe-0000002")));
    await fixture.jobs().tick();
    await fixture.jobs().tick();
    expect((await fixture.outboxRows())[0]?.state).toBe("delivered");
  });
  it("retries definite rejections up to the attempt limit then fails", async () => {
    fixture.sender.behavior = async () => ({ status: "rejected", reason: "HTTP_503" });
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("reject-0000001")));
    for (let i = 0; i < 7; i++) await fixture.jobs().tick();
    expect((await fixture.outboxRows())[0]).toMatchObject({
      state: "failed",
      attempts: 5,
      lastError: "HTTP_503",
    });
  });
  it("lets the owner abandon an uncertain intent and rejects a stale expected state", async () => {
    fixture.sender.behavior = async () => ({ status: "unknown" });
    await fixture
      .jobs()
      .transact((tx) => fixture.jobs().enqueueOutbox(tx, fixture.intent("abandon-000001")));
    await fixture.jobs().tick();
    const [row] = await fixture.outboxRows();
    await expect(reconcile(row?.id ?? "", "held", "abandon")).rejects.toMatchObject({
      code: "REVISION_CONFLICT",
    });
    expect((await reconcile(row?.id ?? "", "unknown", "abandon")).state).toBe("failed");
  });
  it("creates outbox intent from a job handler tied to its own run", async () => {
    const definition = await fixture.register();
    fixture.handler.script = async (context) => {
      await context.outbox({
        effectKey: `${context.effectKey}:notify`,
        destination: "fixture.sink",
        payload: { ok: true },
      });
      return { status: "succeeded", evidenceRef: "fixture:enqueued" };
    };
    const run = await fixture.trigger(definition.id, 0, "handler-out-001");
    await fixture.work();
    await fixture.jobs().tick();
    const [row] = await fixture.outboxRows();
    expect(row).toMatchObject({ jobRunId: run.id, state: "delivered" });
    expect(fixture.sender.sends[0]).toMatchObject({
      projectId: fixture.project.id,
      environmentId: fixture.development.id,
    });
  });
  it("refuses new outbox intent from a worker whose lease has expired", async () => {
    const definition = await fixture.register({ effectPolicy: "protected" });
    const started = deferred();
    const release = deferred();
    let lateIntent: Promise<unknown> | undefined;
    fixture.handler.script = async (context) => {
      started.resolve();
      await release.promise;
      lateIntent = context
        .outbox({
          effectKey: `${context.effectKey}:late`,
          destination: "fixture.sink",
          payload: {},
        })
        .catch((error: unknown) => error);
      await lateIntent;
      return { status: "succeeded", evidenceRef: "late:result" };
    };
    await fixture.trigger(definition.id, 0, "stale-intent-001");
    await fixture.jobs().tick();
    const worker = fixture.infrastructure.foundation.tick("stale-worker");
    await started.promise;
    fixture.clock.advance(120_000);
    await fixture.infrastructure.foundation.reconcileExpired();
    release.resolve();
    await worker;
    expect(await lateIntent).toBeInstanceOf(Error);
    expect(await fixture.outboxRows()).toHaveLength(0);
  });
});
